?>
<!DOCTYPE html><html lang="<?php echo function_exists('stridebr_html_lang') ? stridebr_e(stridebr_html_lang()) : 'pt-BR'; ?>"><head>
    <?php if (function_exists('stridebr_ui_boot_script')) echo stridebr_ui_boot_script(); ?><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><link rel="stylesheet" href="<?php echo stridebr_e(stridebr_asset('/assets/css/style.css')); ?>"><link rel="stylesheet" href="<?php echo stridebr_e(stridebr_asset('/assets/css/ui-refresh.css')); ?>"><link rel="stylesheet" href="<?php echo stridebr_e(stridebr_asset('/assets/css/product-insights.css')); ?>"><title><?php echo stridebr_e((string)$schedule['nome']); ?> | StrideBR</title></head><body><div class="container-fluid"><?php require dirname(__DIR__,2).'/src/layout/header.php'; ?><main class="main-content product-page"><header class="product-page-header"><div><span class="eyebrow">Cronograma sincronizado</span><h1><?php echo stridebr_e((string)$schedule['nome']); ?></h1><p><?php echo stridebr_e((string)($schedule['descricao']?:'Este cronograma acompanha as alterações feitas pelo dono.')); ?></p></div><div class="product-toolbar"><a class="product-button-secondary" href="/user/amigos.php#cronogramas-sincronizados">Gerenciar acesso</a><?php if((string)$schedule['papel']==='owner'): ?><a class="product-button" href="/user/cronogramatreinos.php?id=<?php echo rawurlencode($idCronograma); ?>">Editar</a><?php endif; ?></div></header><div class="privacy-note">Mantido por <?php echo stridebr_e(stridebr_person_name_for_display((string)$schedule['dono_nome'],(string)($schedule['dono_username']??''),'Usuário',60)); ?>. Como participante em modo leitura, você vê sempre a versão atual sem criar uma cópia.</div><?php if(!$workouts): ?><section class="empty-action-state" style="margin-top:18px"><h2>Este cronograma ainda não tem treinos</h2><p>Quando o dono adicionar um treino, ele aparecerá aqui automaticamente.</p></section><?php else: ?><section class="insight-section"><header><div><h2>Semana</h2><p class="insight-muted"><?php echo count($workouts); ?> treino<?php echo count($workouts)===1?'':'s'; ?> no cronograma atual.</p></div></header><div class="notification-list"><?php foreach($workouts as $workout): ?><article class="sync-card"><div><strong><?php echo stridebr_e((string)$workout['titulo']); ?></strong><p class="insight-muted"><?php echo stridebr_e($days[(int)$workout['dia_semana']]??''); ?> · <?php echo stridebr_e(substr((string)$workout['hora_inicio'],0,5)); ?><?php if(!empty($workout['foco'])): ?> · <?php echo stridebr_e((string)$workout['foco']); ?><?php endif; ?></p><?php if($workout['exercicios']): ?><details><summary><?php echo count($workout['exercicios']); ?> exercício<?php echo count($workout['exercicios'])===1?'':'s'; ?></summary><table class="compare-table"><tbody><?php foreach($workout['exercicios'] as $exercise): ?><tr><td><?php echo stridebr_e((string)$exercise['nome']); ?></td><td><?php echo $exercise['series']!==null?(int)$exercise['series'].' séries':'—'; ?></td><td><?php echo stridebr_e((string)($exercise['repeticoes']??'—')); ?><?php echo !empty($exercise['carga'])?' · '.stridebr_e((string)$exercise['carga']):''; ?></td></tr><?php endforeach; ?></tbody></table></details><?php endif; ?></div></article><?php endforeach; ?></div></section><?php endif; ?></main></div><?php require dirname(__DIR__,2).'/src/layout/footer.php'; ?></body></html>
